('07d0dc58-8ab1-54e7-86c3-c5d771fb142d','quiz_paper','CBSE',10,'Science','Acids, Bases and Salts',NULL,'Quiz Paper: Acids, Bases and Salts (Class 10 Science)','medium',20,30,'{"sections": [{"name": "Section A \u2014 MCQ", "questions": [{"question": "HCF of 12 and 18 is:", "options": ["a) 2", "b) 3", "c) 6", "d) 36"], "correct_option": "c", "explanation": "12 = 2\u00b2\u00d73, 18 = 2\u00d73\u00b2 \u2192 HCF = 2\u00d73 = 6.", "marks": 4}, {"question": "x\u00b2 - 5x + 6 = 0 has roots:", "options": ["a) 2 and 3", "b) -2 and -3", "c) 1 and 6", "d) -1 and -6"], "correct_option": "a", "explanation": "Factorise: (x-2)(x-3) = 0.", "marks": 4}, {"question": "The focal length of a spherical mirror of radius of curvature 30 cm is:", "options": ["a) 60 cm", "b) 30 cm", "c) 15 cm", "d) 7.5 cm"], "correct_option": "c", "explanation": "f = R/2 = 30/2 = 15 cm.", "marks": 4}, {"question": "The sum of first 10 natural numbers is:", "options": ["a) 45", "b) 50", "c) 55", "d) 60"], "correct_option": "c", "explanation": "n(n+1)/2 = 10\u00d711/2 = 55.", "marks": 4}, {"question": "The SI unit of power of a lens is:", "options": ["a) Watt", "b) Dioptre", "c) Metre", "d) Candela"], "correct_option": "b", "explanation": "Power = 1/f(in metres), measured in dioptres (D).", "marks": 4}]}]}','ollama_local',NULL,'PUBLISHED',TRUE,'2026-06-30T14:31:53.276987+00:00'),
